   256	    /// Evaluate (plugin_id, operation) against all Deny rules in the compliance graph.
   257	    pub fn evaluate_mutation(&self, plugin_id: &str, operation: &str) -> PolicyVerdict {
   258	        let query = r#"
   259	            deny_rule[reason] :=
   260	                *compliance_rule[plugin, op, action, reason, _, _],
   261	                action = 'Deny',
   262	                (plugin = $plugin || plugin = '*'),
   263	                (op = $op || op = '*')
   264	            ?[reason] := deny_rule[reason]
   265	        "#;
   266	        let mut p: Params = BTreeMap::new();
   267	        p.insert("plugin".into(), DataValue::Str(plugin_id.into()));
   268	        p.insert("op".into(), DataValue::Str(operation.into()));
   269	
   270	        match cozo_run(&self.db, query, p) {
   271	            Ok(rows) if rows.rows.is_empty() => PolicyVerdict {
   272	                allow: true,
   273	                reason: "no deny rule matched".into(),
   274	            },
   275	            Ok(rows) => {
   276	                let reason = rows.rows[0]
   277	                    .first()
   278	                    .and_then(dv_as_str)
   279	                    .unwrap_or("compliance rule violated")
   280	                    .to_string();
   281	                PolicyVerdict {
   282	                    allow: false,
   283	                    reason,
   284	                }
   285	            }
   286	            Err(_) => PolicyVerdict {
   287	                allow: true,
   288	                reason: "compliance graph not seeded".into(),
   289	            },
   290	        }
   291	    }
