   448	    /// BFS traversal using CozoDB's native recursive rules.
   449	    pub fn traverse_graph(
   450	        &self,
   451	        start_node: &str,
   452	        max_depth: u32,
   453	    ) -> std::result::Result<Value, CozoError> {
   454	        let query = r#"
   455	            reachable[to, d] := to = $start, d = 0
   456	            reachable[to, d] := reachable[from, d0], *graph_edge[from, _, to, _],
   457	                                d = d0 + 1, d <= $max_depth
   458	            ?[node, depth] := reachable[node, depth]
   459	            :order depth
   460	        "#;
   461	        let mut p: Params = BTreeMap::new();
   462	        p.insert("start".into(), DataValue::Str(start_node.into()));
   463	        p.insert("max_depth".into(), dv_int(max_depth as i64));
   464	        let r = cozo_run(&self.db, query, p)
   465	            .map_err(|e| CozoError::Other(format!("traverse graph: {e}")))?;
   466	        Ok(named_rows_to_json(r))
   467	    }
