    41	#[allow(clippy::result_large_err)]
    42	pub fn ghostbridge_interceptor(mut req: Request<()>) -> Result<Request<()>, Status> {
    43	    // 1. Extract the Xray-injected Identity Headers (The Accountability Loop)
    44	    //    Clone header values upfront to release the immutable borrow on `req`,
    45	    //    allowing the mutable `extensions_mut()` call downstream.
    46	    let footprint_value = req.metadata().get("x-ghostbridge-footprint").cloned();
    47	    let trace_value = req
    48	        .metadata()
    49	        .get("x-ghostbridge-trace-id")
    50	        .or_else(|| req.metadata().get("x-wireguard-pubkey"))
    51	        .cloned();
    52	
    53	    if footprint_value.is_none() || trace_value.is_none() {
    54	        return Err(Status::unauthenticated(
    55	            "A.N.N.A. Scribe: Missing Ghostbridge Identity Sled. Connection Dropped.",
    56	        ));
    57	    }
    58	
    59	    // 2. 1:1 Direct Read from the MutationEngine's shared memory (No SQL, No Polling)
    60	    let (sled_ptr, _mmap) = op_identity::read_sled()
    61	        .map_err(|_| Status::internal("MutationEngine Memory Unreachable"))?;
    62	    let sled = unsafe { &*sled_ptr };
    63	
    64	    // The Absolute Base: No valid schema, it does not exist.
    65	    if !is_sled_valid(sled) {
    66	        return Err(Status::failed_precondition(
    67	            "A.N.N.A. Scribe: Invalid Schema State. Cease and Desist.",
    68	        ));
    69	    }
    70	
    71	    let current_footprint = sled.hashed_footprint;
    72	
    73	    // 3. The Strike/Etch Validation: Check if the payload is in sync with Btrfs.
    74	    //    If a Btrfs mutation has occurred and the client's footprint is stale,
    75	    //    the connection is dropped without consuming any NVMe I/O.
    76	    let request_footprint = footprint_value
    77	        .as_ref()
    78	        .unwrap()
    79	        .to_str()
    80	        .map_err(|_| Status::invalid_argument("Invalid footprint header encoding"))?;
    81	    let expected_footprint = hex::encode(current_footprint);
    82	
    83	    if request_footprint != expected_footprint {
    84	        return Err(Status::permission_denied(
    85	            "A.N.N.A. Scribe: Temporal Hash Mismatch. \
    86	             Session footprint is out of sync with current Btrfs mutation.",
    87	        ));
    88	    }
    89	
    90	    // 4. Pass the Trace ID downstream into the gRPC context for the React GUI.
    91	    let session_id = trace_value
    92	        .as_ref()
    93	        .expect("trace checked above")
    94	        .to_str()
    95	        .map_err(|_| Status::invalid_argument("Invalid trace header encoding"))?
    96	        .to_string();
    97	    req.extensions_mut().insert(GhostbridgeIdentity {
    98	        footprint: request_footprint.to_string(),
    99	        session_id,
   100	    });
   101	
   102	    Ok(req)
   103	}
